"""Typed input events for voice event composition."""

from __future__ import annotations

import time
from abc import ABC
from datetime import datetime, timezone
from enum import Enum
from typing import Any, Dict, Optional, Union

from pydantic import BaseModel, ConfigDict, Field

from rasa.core.channels.constants import (
    USER_CONVERSATION_SESSION_END,
    USER_CONVERSATION_SESSION_START,
    USER_CONVERSATION_SILENCE_TIMEOUT,
)
from rasa.shared.core.playback_marker import PlaybackPosition


class MarkerType(str, Enum):
    """A structural beacon in the bot audio stream sent to the client."""

    START = "start"
    INTERMEDIATE = "intermediate"
    END = "end"


class InputEvent(BaseModel, ABC):
    """Base for all input events sent from channels to Rasa via queue."""

    model_config = ConfigDict(frozen=True)

    # UTC wall-clock timestamp
    created_at: datetime = Field(
        default_factory=lambda: datetime.now(timezone.utc),
    )
    # Process-local monotonic timestamp for reliable elapsed-time measurements.
    created_at_monotonic: float = Field(
        default_factory=lambda: time.monotonic(), exclude=True, repr=False
    )


class VoiceInputEvent(InputEvent):
    """Base class for all voice-specific input events."""

    text: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None


class SessionStartedInputEvent(VoiceInputEvent):
    """Marks the beginning of a voice session.

    Sent when a WebSocket connects and call parameters are established.

    Attributes:
        text: constant string
        metadata: The call parameters for this session.
    """

    metadata: Dict[str, Any] = Field(default_factory=dict)
    text: str = Field(default=USER_CONVERSATION_SESSION_START, init=False)


class FinalTranscriptInputEvent(VoiceInputEvent):
    """A finalised ASR transcript for one voice turn.

    Attributes:
        text: The final transcript text from ASR.
        metadata: Optional metadata from the channel (e.g. ASR confidence).
    """

    text: str
    metadata: Optional[Dict[str, Any]] = None


class PartialTranscriptInputEvent(VoiceInputEvent):
    """A partial ASR transcript for an in-progress voice turn."""

    text: str
    metadata: Optional[Dict[str, Any]] = None


class DTMFKeypressInputEvent(VoiceInputEvent):
    """A raw DTMF keypress from the voice transport."""

    digit: str
    metadata: Optional[Dict[str, Any]] = None


class SilenceDetectedInputEvent(VoiceInputEvent):
    """Signals a period of user silence or an elapsed silence timeout."""

    text: str = Field(default=USER_CONVERSATION_SILENCE_TIMEOUT, init=False)
    metadata: Optional[Dict[str, Any]] = None


class SessionEndedInputEvent(VoiceInputEvent):
    """Marks the end of a voice session.

    Sent when the call terminates or the WebSocket disconnects.
    """

    text: str = Field(default=USER_CONVERSATION_SESSION_END, init=False)
    metadata: Optional[Dict[str, Any]] = None


class PlaybackMarkerSentInputEvent(VoiceInputEvent):
    """Channel sent a playback marker to the client.

    Intermediate markers carry ``position``, where playback had reached.
    """

    marker_id: str
    marker_type: Optional[MarkerType] = None
    position: Optional[PlaybackPosition] = None
    metadata: Optional[Dict[str, Any]] = None


class PlaybackMarkerAcknowledgedInputEvent(VoiceInputEvent):
    """Client acknowledged a playback marker."""

    marker_id: str
    metadata: Optional[Dict[str, Any]] = None


class BotPlaybackStartedInputEvent(VoiceInputEvent):
    """The client started playing bot audio.

    Emitted by channels that report playback natively instead of echoing playback
    markers (e.g. Genesys, AudioCodes). Marker channels use
    ``PlaybackMarker*InputEvent`` instead.
    """

    metadata: Optional[Dict[str, Any]] = None


class BotPlaybackStoppedInputEvent(VoiceInputEvent):
    """The client finished playing bot audio.

    Counterpart to ``BotPlaybackStartedInputEvent`` for channels that report
    playback natively rather than via playback markers.
    """

    metadata: Optional[Dict[str, Any]] = None


LifecycleInputEvent = Union[SessionStartedInputEvent, SessionEndedInputEvent]

TranscriptInputEvent = Union[PartialTranscriptInputEvent, FinalTranscriptInputEvent]

BotPlaybackInputEvent = Union[
    PlaybackMarkerSentInputEvent,
    PlaybackMarkerAcknowledgedInputEvent,
    BotPlaybackStartedInputEvent,
    BotPlaybackStoppedInputEvent,
]
